corrected_code:
const express = require('express');
const { trace } = require('@opentelemetry/api');

const app = express();
const jobSpanRegistry = new Map();

app.get('/telemetry/jobs/:jobSpanId', (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const jobSpan = jobSpanRegistry.get(req.params.jobSpanId);
  if (!jobSpan) {
    return res.status(404).json({ error: 'Job span not found' });
  }

  // Validate that the job's organization matches the caller's organization
  if (jobSpan.attributes['tenant.organization_id'] !== req.user.organizationId) {
    return res.status(403).json({ error: 'Access denied: ETL job belongs to another organization' });
  }

  res.json({
    jobSpanId: req.params.jobSpanId,
    datasetSourceUri: jobSpan.attributes['etl.s3_source_uri'],
    recordCount: jobSpan.attributes['etl.row_count'],
    executionDurationMs: jobSpan.attributes['etl.duration_ms']
  });
});

app.listen(6066);
